var n=`1405-rourou`;var t=`world-1405`;var a=`FJ`;var o=`oceania`;var s=4;var l=34;var u={en:`Rourou`,ua:`Руру`};var c={en:`Fijian rourou is traditionally taro leaves simmered in coconut milk. This catalog adaptation uses spinach because edible taro leaves are absent.`,ua:`Руру на Фіджі традиційно готують з листя таро, томленого в кокосовому молоці. Через відсутність листя таро в каталозі тут використано шпинат.`};var r=[{en:`Finely chop onion and garlic and sauté in coconut oil until translucent.`,ua:`Дрібно наріжте цибулю та часник і обсмажте в кокосовій олії до прозорості.`,t:[`chopping`,`sauteing`],m:7,i:[[`yellow-onion`,100,`g`],[`garlic`,3,`clove`],[`coconut-oil`,15,`ml`]]},{en:`Wash spinach thoroughly, chop roughly, and add it to the pan; stir until wilted.`,ua:`Ретельно промийте шпинат, грубо поріжте та додайте до сковороди; перемішуйте, поки зелень не зів’яне.`,t:[`chopping`,`sauteing`],m:6,i:[[`spinach`,450,`g`]]},{en:`Pour in coconut milk, season with salt, and simmer gently 15–20 minutes to soften the greens and thicken the sauce.`,ua:`Влийте кокосове молоко, посоліть і тушкуйте на слабкому вогні 15–20 хвилин, щоб зелень розм’якшилася, а соус загус.`,t:[`simmering`],m:18,i:[[`coconut-milk`,350,`ml`],[`sea-salt`,4,`g`]]},{en:`Finish with a little lime juice and serve with cooked taro or rice.`,ua:`Наприкінці додайте трохи соку лайма та подавайте з готовим таро або рисом.`,t:[`finishing-with-acid`],m:3,i:[[`lime-juice`,15,`ml`]]}];var h={slug:n,id:t,country:`FJ`,region:o,servings:4,minutes:34,title:u,text:c,steps:r};export{a as country,h as default,t as id,l as minutes,o as region,s as servings,n as slug,r as steps,c as text,u as title};